create policy "recordings_storage_insert" on storage.objects for insert to authenticated with check (bucket_id = 'recordings' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "recordings_storage_select" on storage.objects for select to authenticated using (bucket_id = 'recordings' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "recordings_storage_delete" on storage.objects for delete to authenticated using (bucket_id = 'recordings' and (storage.foldername(name))[1] = auth.uid()::text);